    timingLog?.call(
      'resume_timing open file=${filePath.split('/').last} '
      'mode=full lock_wait_ms=${sw.elapsedMilliseconds - storage._openInnerMs} '
      'total_ms=${sw.elapsedMilliseconds}',
    );
    return storage;
  }

